import{_ as t,o as d,c as a,ag as o}from"./chunks/framework.DaCm-iTo.js";const p=JSON.parse('{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/gem/commands.md","filePath":"modules/gem/commands.md","lastUpdated":null}'),i={name:"modules/gem/commands.md"};function c(s,e,r,l,n,m){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to &quot;命令与权限&quot;">​</a></h1><p>EmakiGem 的主命令是 <code>/emakigem</code>，别名为 <code>/egem</code>、<code>/eg</code>。玩家用它打开镶嵌、开孔或升级界面；管理员用它检查装备宝石状态、清理异常状态、重载配置和输出调试信息。</p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to &quot;命令列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/emakigem help</code></td><td>无</td><td>输出命令帮助列表。不带参数执行 <code>/emakigem</code> 时同样显示。</td></tr><tr><td>`/emakigem gui &lt;inlay</td><td>open</td><td>upgrade&gt;`</td></tr><tr><td><code>/emakigem reload</code></td><td><code>emakigem.reload</code> 或 <code>emakigem.admin</code></td><td>重载主配置、宝石定义、插槽物品、共鸣、条件、GUI 和语言文件。</td></tr><tr><td><code>/emakigem inspect [player]</code></td><td><code>emakigem.use</code> 或 <code>emakigem.admin</code></td><td>查看指定玩家或自己的主手装备宝石状态。</td></tr><tr><td><code>/emakigem clearstate</code></td><td><code>emakigem.admin</code></td><td>清除主手物品的宝石层状态，适合调试或修复异常装备。</td></tr><tr><td><code>/emakigem debug</code></td><td><code>emakigem.debug</code> 或 <code>emakigem.admin</code></td><td>输出运行时调试信息。</td></tr></tbody></table><h2 id="gui-模式" tabindex="-1">GUI 模式 <a class="header-anchor" href="#gui-模式" aria-label="Permalink to &quot;GUI 模式&quot;">​</a></h2><p><code>gui</code> 命令支持三种模式：</p><table tabindex="0"><thead><tr><th>模式</th><th>作用</th><th>常见用途</th></tr></thead><tbody><tr><td><code>inlay</code></td><td>镶嵌与提取宝石</td><td>玩家日常宝石操作。</td></tr><tr><td><code>open</code></td><td>开孔</td><td>使用开孔器解锁装备预留插槽。</td></tr><tr><td><code>upgrade</code></td><td>宝石升级</td><td>消耗材料和货币提升宝石等级。</td></tr></tbody></table><p>示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/emakigem gui inlay</span></span>\n<span class="line"><span>/emakigem gui open</span></span>\n<span class="line"><span>/emakigem gui upgrade</span></span></code></pre></div><p>如果希望玩家只通过菜单入口进入某一类操作，可以在其他菜单插件或 NPC 插件中执行对应命令，并把权限控制交给 <code>emakigem.use</code>。</p><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to &quot;权限节点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>emakigem.use</code></td><td>true</td><td>允许使用基础宝石功能和打开 GUI。</td></tr><tr><td><code>emakigem.reload</code></td><td>op</td><td>允许重载配置。</td></tr><tr><td><code>emakigem.admin</code></td><td>op</td><td>允许检查、清理状态等管理操作。</td></tr><tr><td><code>emakigem.debug</code></td><td>op</td><td>允许输出调试信息。</td></tr></tbody></table><h2 id="先用哪个命令" tabindex="-1">先用哪个命令 <a class="header-anchor" href="#先用哪个命令" aria-label="Permalink to &quot;先用哪个命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>先执行</th><th>目的</th></tr></thead><tbody><tr><td>玩家要镶嵌或提取宝石</td><td><code>/emakigem gui inlay</code></td><td>打开镶嵌界面。</td></tr><tr><td>玩家要给装备开孔</td><td><code>/emakigem gui open</code></td><td>打开开孔界面。</td></tr><tr><td>玩家要升级宝石</td><td><code>/emakigem gui upgrade</code></td><td>打开升级界面。</td></tr><tr><td>装备宝石状态异常</td><td><code>/emakigem inspect [player]</code></td><td>查看主手装备 gem layer、插槽和共鸣状态。</td></tr><tr><td>主手装备需要清理宝石层</td><td><code>/emakigem clearstate</code></td><td>移除主手物品的宝石状态。先备份。</td></tr><tr><td>改了宝石、插槽物品、共鸣或 GUI</td><td><code>/emakigem reload</code></td><td>重载运行配置。</td></tr></tbody></table><h2 id="常见操作" tabindex="-1">常见操作 <a class="header-anchor" href="#常见操作" aria-label="Permalink to &quot;常见操作&quot;">​</a></h2><h3 id="打开宝石界面" tabindex="-1">打开宝石界面 <a class="header-anchor" href="#打开宝石界面" aria-label="Permalink to &quot;打开宝石界面&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/emakigem gui inlay</span></span></code></pre></div><p>命令模式必须明确写 <code>inlay</code>、<code>open</code> 或 <code>upgrade</code>。<code>gui.default_mode</code> 只作为 GUI 服务默认值，不替代命令参数。</p><h3 id="检查装备宝石状态" tabindex="-1">检查装备宝石状态 <a class="header-anchor" href="#检查装备宝石状态" aria-label="Permalink to &quot;检查装备宝石状态&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/emakigem inspect Steve</span></span></code></pre></div><p>检查内容包括装备是否拥有 gem layer、已开放插槽、已镶嵌宝石、共鸣状态以及可回退的物品操作记录。排查“属性未生效”“宝石显示残留”“提取后效果未撤销”等问题时优先使用该命令。</p><h3 id="清理异常状态" tabindex="-1">清理异常状态 <a class="header-anchor" href="#清理异常状态" aria-label="Permalink to &quot;清理异常状态&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/emakigem clearstate</span></span></code></pre></div><p>该命令会清除主手物品上的宝石状态。使用前建议备份玩家物品数据，并先通过 <code>inspect</code> 确认目标物品。清理后装备会失去宝石层记录，原有宝石效果不会再按正常流程保留。</p><h2 id="排查建议" tabindex="-1">排查建议 <a class="header-anchor" href="#排查建议" aria-label="Permalink to &quot;排查建议&quot;">​</a></h2><ul><li>GUI 打不开：检查玩家是否拥有 <code>emakigem.use</code>，并确认 GUI 模板目录存在。</li><li>开孔失败：检查目标装备是否匹配 <code>items/*.yml</code>，并确认存在未开放且类型匹配的预留插槽。</li><li>镶嵌失败：检查宝石 <code>socket_compatibility</code>、插槽类型、条件配置、费用配置和 <code>inlay_success</code>。</li><li>升级失败：检查宝石升级配置、目标等级材料、经济插件与全局失败惩罚。</li><li>属性未刷新：检查 EmakiAttribute 是否安装，装备是否重建，宝石效果是否写入 <code>ea_attribute</code>。</li></ul>',26)])])}const g=t(i,[["render",c]]);export{p as __pageData,g as default};
